import 'dart:convert';import 'package:flutter/material.dart';import 'package:flutter_secure_storage/flutter_secure_storage.dart';import 'package:flutter_test/flutter_test.dart';import 'package:integration_test/integration_test.dart';
import 'package:mobile_shared/mobile_api.dart';import 'package:mobile_shared/bitpos_theme.dart';import 'package:bitpos_driver/earnings_page.dart';
void main(){final binding=IntegrationTestWidgetsFlutterBinding.ensureInitialized();testWidgets('AVD owned actual persisted earning payout and logout privacy',(tester)async{
 if(!const bool.fromEnvironment('BITPOS_FIXTURE'))throw StateError('Explicit local fixture required');
 final session=jsonDecode(utf8.decode(base64Decode(const String.fromEnvironment('BITPOS_TEST_SESSION_BASE64'))));
 FlutterSecureStorage.setMockInitialValues({'bitpos.mobileSession':jsonEncode(session),'bitpos.deviceId':const String.fromEnvironment('BITPOS_TEST_DEVICE_ID')});
 final api=MobileApi(base:Uri.parse(const String.fromEnvironment('BITPOS_MOBILE_API')),fixture:true);await api.restore();addTearDown(api.close);expect(api.signedIn,isTrue);
 Future<void> visible(Finder finder)async{final end=DateTime.now().add(const Duration(seconds:35));while(finder.evaluate().isEmpty&&DateTime.now().isBefore(end)){await tester.pump(const Duration(milliseconds:100));if(find.byType(ListView).evaluate().isNotEmpty){await tester.drag(find.byType(ListView).last,const Offset(0,-250));await tester.pump();}}expect(finder,findsOneWidget);}
 await tester.pumpWidget(MaterialApp(theme:BitPosTheme.light(),home:DriverEarningsPage(api:api,thai:false)));
 await tester.pump();final summary=tester.getRect(find.byKey(const ValueKey('driver-earnings-summary')));debugPrint('BITPOS_EARNINGS088_GEOMETRY ${jsonEncode({'left':summary.left,'top':summary.top,'width':summary.width,'height':summary.height,'logicalWidth':tester.view.physicalSize.width/tester.view.devicePixelRatio,'dpr':tester.view.devicePixelRatio})}');debugPrint('BITPOS_EARNINGS088_SUMMARY_VISIBLE');await tester.runAsync(()=>Future<void>.delayed(const Duration(seconds:2)));
 await visible(find.text('Eligible — not transferred'));expect(find.text('1.00 USD'),findsOneWidget);expect(find.textContaining('1.000000 USDG'),findsOneWidget);debugPrint('BITPOS_EARNINGS088_EN_VISIBLE');await tester.runAsync(()=>Future<void>.delayed(const Duration(seconds:2)));
 await tester.ensureVisible(find.text('Payouts'));await tester.tap(find.text('Payouts'));await tester.pump();await visible(find.text('Draft cancelled'));expect(find.textContaining('No finalized transfer receipt'),findsOneWidget);debugPrint('BITPOS_EARNINGS088_PAYOUT_VISIBLE');await tester.runAsync(()=>Future<void>.delayed(const Duration(seconds:2)));
 await tester.pumpWidget(MaterialApp(theme:BitPosTheme.light(),home:DriverEarningsPage(api:api,thai:true)));await tester.pump();await visible(find.text('ยกเลิกเฉพาะร่างรอบจ่าย'));expect(find.textContaining('ยังไม่มีหลักฐานการโอนขั้นสุดท้าย'),findsOneWidget);debugPrint('BITPOS_EARNINGS088_TH_VISIBLE');await tester.runAsync(()=>Future<void>.delayed(const Duration(seconds:2)));
 await tester.runAsync(()=>api.logout());await tester.pump();expect(find.text('เซสชันเปลี่ยนแล้ว กลับไปเข้าสู่ระบบใหม่'),findsOneWidget);expect(find.textContaining('1.000000 USDG'),findsNothing);expect(find.textContaining('1.00 USD'),findsNothing);debugPrint('BITPOS_EARNINGS088_RETIRED');await tester.runAsync(()=>Future<void>.delayed(const Duration(seconds:2)));
 binding.reportData={'status':'PASS_AVD_ACTUAL_API_OWN_EARNINGS_PAYOUT_LOGOUT','fixture':true,'physicalTesting':'deferred_by_user_2026-10-16','limits':['Synthetic payment/identity and fixture secure storage only','No transferred funds or physical-device/provider readiness']};
});}
